INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(26601, 'Acts 22:28', 'Acts', 22, 28, '&nbsp;کمان آفسر ورته ووئيل چې، ”ما خو په لوئ قيمت دا مقامى حق اخستے دے.“ پولوس ورته ووئيل ”خو دا زما قومى حق دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26602, 'Acts 22:29', 'Acts', 22, 29, '&nbsp;نو سمدستى هغه څوک چې د هغۀ نه تفتيش کوونکى وُو د هغۀ نه وروستو شول، او کمان آفسر هم وويرېدو ځکه چې هغۀ ته پته ولګېده چې پولوس مقامى رومى دے او هغۀ تړلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26603, 'Acts 22:30', 'Acts', 22, 30, '&nbsp;په بله ورځ کمان آفسر غوښتل چې صحيح معلومات تر لاسه کړى چې يهوديانو ولې په پولوس اِلزام ولګولو. هغۀ پولوس آزاد کړو او مشرانو اِمامانو او ټولې اولسى جرګې ته يې حُکم ورکړو چې، ”راټول شئ،“ بيا هغۀ پولوس ښکته راوستلو او د هغوئ په وړاندې يې ودرولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26604, 'Acts 23:1', 'Acts', 23, 1, '&nbsp;پولوس جرګې ته په اوچتو سترګو وکتل او وې وئيل چې، ”اے زما وروڼو، تر نن ورځې ما په صفا ضمير سره د خُدائ پاک په وړاندې خپل ژوند تير کړے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26605, 'Acts 23:2', 'Acts', 23, 2, '&nbsp;بيا مشر اِمام حنانياس پولوس سره ولاړو خلقو ته حُکم ورکړو چې، ”په خولۀ يې ووهئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26606, 'Acts 23:3', 'Acts', 23, 3, '&nbsp;په دې پولوس هغۀ ته ووئيل چې، ”خُدائ پاک به تا ووهى، اے مکاره، تۀ ناست يې چې د شريعت په مطابق زما فېصله وکړې، او اوس تۀ د شريعت خلاف زما د وهلو حُکم ورکوې څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26607, 'Acts 23:4', 'Acts', 23, 4, '&nbsp;خو څوک چې نزدې ولاړ وو وئ وئيل چې، ”تۀ د خُدائ پاک د مشر اِمام بې‌عزتى کوې څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26608, 'Acts 23:5', 'Acts', 23, 5, '&nbsp;او پولوس ووئيل چې، ”زما وروڼو، ما ته پته نۀ وه چې هغه مشر اِمام دے. ځکه چې صحيفې وائى چې، تاسو د خپل قوم حاکِم ته بدرد مۀ وايئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26609, 'Acts 23:6', 'Acts', 23, 6, '&nbsp;بيا کله چې پولوس ته پته ولګېده چې په دوئ کښې يوه ډله د صدوقيانو ده او بله د فريسيانو نو هغۀ په جرګه کښې چغې کړې چې، ”اے زما وروڼو، زۀ يو فريسى يم او د فريسى زوئ يم. زما اُميد دے چې مړى به بيا راژوندى کيږى، نو په دې وجه زما تحقيقات کيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26610, 'Acts 23:7', 'Acts', 23, 7, '&nbsp;کله چې هغۀ دا ووئيل نو د فريسيانو او صدوقيانو په مينځ کښې اختلاف شروع شو او جرګه په مينځ دوه ځايه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26611, 'Acts 23:8', 'Acts', 23, 8, '&nbsp;ځکه چې صدوقيان وائى چې نۀ قيامت نۀ فرښتې او نۀ روح شته، خو فريسيان درې واړه منى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26612, 'Acts 23:9', 'Acts', 23, 9, '&nbsp;بيا لويه غوغا جوړه شوه او د فريسيانو د فرقې ځينې د شرعې عالمان راپاڅېدل او په کلکه يې ووئيل چې، ”مونږ په دې سړى کښې هيڅ غلطى نۀ وينو. شايد چې يوې فرښتې يا روح ورسره خبرې کړې وې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26613, 'Acts 23:10', 'Acts', 23, 10, '&nbsp;کله چې بلوه زياته شوه نو کمان آفسر ويرېدو هسې نه چې دوئ پولوس ټوټې ټوټې کړى، نو هغۀ سپاهيانو ته حُکم وکړو چې، ”لاندې لاړ شئ او هغه د هغوئ نه په زور راولئ او قلعې ته يې دننه راولئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26614, 'Acts 23:11', 'Acts', 23, 11, '&nbsp;په هغه شپه مالِک پولوس ته ظاهر شو او ورته يې وفرمائيل چې، ”تکړه شه، ځکه څنګه چې تا په يروشلم کښې زما په حق کښې ګواهى کړې وه، نو هم دغه شان يې په روم کښې هم وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26615, 'Acts 23:12', 'Acts', 23, 12, '&nbsp;په سحر کښې يهوديان د يو سازش دپاره راغونډ شول او خپلو کښې يې سره دا قَسم وکړو چې نۀ به څۀ خورو او نۀ به څۀ څښو ترڅو چې دوئ پولوس وژلے نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26616, 'Acts 23:13', 'Acts', 23, 13, '&nbsp;د څلوېښتو کسانو نه زيات په دې سازش کښې شامل وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26617, 'Acts 23:14', 'Acts', 23, 14, '&nbsp;هغوئ مشرانو اِمامانو او د جرګې مشرانو له ورغلل او وې وئيل چې، ”مونږ په خپلو کښې پوخ قَسم کړے دے چې تر هغې به نۀ څۀ خورو او نۀ څۀ څښو ترڅو چې مونږ پولوس مړ نۀ کړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26618, 'Acts 23:15', 'Acts', 23, 15, '&nbsp;اوس دا ستاسو او د جرګې کار دے چې کمان آفسر ته درخواست وکړئ چې هغه تاسو له لاندې راولى په دې بهانه چې تاسو غواړئ چې د دۀ د مقدمې صحيح تحقيقات وکړئ. مونږ دې ته تيار يُو چې دلته د رارسېدو نه وړاندې هغه قتل کړُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26619, 'Acts 23:16', 'Acts', 23, 16, '&nbsp;خو د پولوس خوريے د هغوئ د سازش نه خبر شو. نو هغه لاړو او قلعې ته ننوتو او پولوس ته يې د هغوئ د سازش ووئيل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26620, 'Acts 23:17', 'Acts', 23, 17, '&nbsp;بيا پولوس يو صوبه دار راوغوښتو او وې وئيل چې، ”دا ځوان کمان آفسر ته بوځه، ځکه چې دے ورته څۀ ضرورى خبره کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26621, 'Acts 23:18', 'Acts', 23, 18, '&nbsp;نو صوبه دار هغه د ځان سره بوتلو او کمان آفسر له يې ور وستو. او وې وئيل چې، ”قېدى پولوس زۀ راوبللم او راته يې ووئيل چې دا ځوان تا ته درولم ځکه چې دے تا ته څۀ ضرورى خبره کول غواړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26622, 'Acts 23:19', 'Acts', 23, 19, '&nbsp;کمان آفسر هغه د لاسه ونيولو، يو طرف ته يې کړو او تپوس يې ترې وکړو چې، ”ما ته ووايه چې څۀ خبره ده؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26623, 'Acts 23:20', 'Acts', 23, 20, '&nbsp;هغۀ ووئيل چې، ”يهوديانو سازش کړے دے چې تا ته عرض وکړى چې سبا له تۀ پولوس د جرګې په وړاندې پېش کړه او د دوئ بهانه دا ده چې د هغۀ د مقدمې پوره پوره تحقيقات کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26624, 'Acts 23:21', 'Acts', 23, 21, '&nbsp;نو تۀ د هغوئ خبره مۀ منه ځکه چې د هغوئ د څلوېښتو کسانو نه زيات سړى په هغۀ د حملې کولو دپاره ناست دى، هغوئ دا قَسم کړے دے چې ترڅو چې هغوئ پولوس مړ نۀ کړى، تر هغې به نۀ څۀ خورى او نۀ څۀ څښى. اوس هغوئ تيار دى خو ستا د حکم اِنتظار دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26625, 'Acts 23:22', 'Acts', 23, 22, '&nbsp;نو کمان آفسر هغه ځوان رُخصت کړو او ورته يې حکم ورکړو چې، ”چا ته ونۀ وائى چې تا ما ته دا اِطلاع راکړې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26626, 'Acts 23:23', 'Acts', 23, 23, '&nbsp;بيا کمان آفسر خپل دوه صوبه داران راوغوښتل او دا حُکم يې ورکړو چې، ”نن شپه نهۀ بجې قيصريه ته د تلو دپاره دوه سوه فوجيان، اويا د آسونو سوارۀ او دوه سوه نېزه بازان تيار کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26627, 'Acts 23:24', 'Acts', 23, 24, '&nbsp;پولوس له هم د سورلۍ بندوبست وکړئ چې هغه پرې سور شى او هغه صحيح سلامت فِليکس ګورنر ته ورسوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26628, 'Acts 23:25', 'Acts', 23, 25, '&nbsp;هغۀ يو خط هم ورته داسې وليکلو چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26629, 'Acts 23:26', 'Acts', 23, 26, '&nbsp;”د کلوديوس لسياس نه معزز ګورنر فِليکس ته سلام.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26630, 'Acts 23:27', 'Acts', 23, 27, '&nbsp;دا سړے يهوديانو نيولے وو او هغوئ وژلو خو چې زۀ خبر شوم چې هغه مقامى رومى دے، نو زۀ سپاهيانو سره ورغلم او دے مې بچ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26631, 'Acts 23:28', 'Acts', 23, 28, '&nbsp;ما دا غوښتل چې دا جُرم معلوم کړم چې هغوئ پرې د کوم اِلزام لګولے دے. نو ما پولوس د هغوئ جرګې ته بوتلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26632, 'Acts 23:29', 'Acts', 23, 29, '&nbsp;زۀ پوهه شوم چې په دۀ باندې د دوئ د شريعت د مسئلو په حقله اِلزام وو، خو څۀ داسې جُرم پرې نۀ وو چې دۀ ته پرې د قېد يا د مرګ سزا ورکړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26633, 'Acts 23:30', 'Acts', 23, 30, '&nbsp;کله چې زۀ خبر شوم چې د دۀ خلاف سازش جوړ شوے دے، نو ما دے سمدستى تا له درولېږلو او مدعيانو ته مې هم حکم ورکړو چې د دۀ په خلاف خپله مقدمه تاسو ته وړاندې کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26634, 'Acts 23:31', 'Acts', 23, 31, '&nbsp;نو د حُکم په مطابق فوجيانو پولوس بوتلو او د شپې يې انتيپترس ښار ته راوستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26635, 'Acts 23:32', 'Acts', 23, 32, '&nbsp;په بله ورځ هغوئ د آسونو سوارۀ د هغۀ سره د مخکښې تلو دپاره پرېښودل او هغوئ قلعې ته راواپس شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26636, 'Acts 23:33', 'Acts', 23, 33, '&nbsp;کله چې هغوئ قيصريه ته راغلل نو خط يې ګورنر له ورکړو او پولوس يې هم د هغۀ په وړاندې پېش کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26637, 'Acts 23:34', 'Acts', 23, 34, '&nbsp;خط يې ولوستو، هغۀ د پولوس نه تپوس وکړو چې تۀ د کومې صوبې اوسېدونکے يې. او کله چې ګورنر خبر شو چې هغه د کلکيه اوسېدونکے دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26638, 'Acts 23:35', 'Acts', 23, 35, '&nbsp;هغۀ ووئيل چې، ”زۀ به ستا مقدمه هله اورم کله چې ستا مدعيان راورسى.“ بيا هغۀ حُکم وکړو چې هغه دې د هيروديس په قلعه کښې وساتلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26639, 'Acts 24:1', 'Acts', 24, 1, '&nbsp;پينځۀ ورځې پس مشر اِمام حنانياس سره د مشرانو او ترطولوس نومې وکيل راغے او هغوئ د ګورنر په وړاندې د پولوس خلاف مقدمه پېش کړله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26640, 'Acts 24:2', 'Acts', 24, 2, '&nbsp;کله چې پولوس راوغوښتے شو نو ترطولوس مقدمه داسې شروع کړه، وئيل يې چې، ”صاحبه، ستا په وجه مونږ په پوره امن ژوند تېروو او ستا د خيال کولو په سبب په دې صوبه کښې د ترقۍ کارونه روان دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26641, 'Acts 24:3', 'Acts', 24, 3, '&nbsp;صاحِبه، مونږ دا خبره په هر ځائ او هر چرته په پوره شُکر ګزارۍ سره منو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26642, 'Acts 24:4', 'Acts', 24, 4, '&nbsp;زۀ ستاسو زيات وخت اخستل نۀ غواړم، خو زۀ درته مِنت کوم چې په مهربانۍ سره زما يو څو خبرې واورئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26643, 'Acts 24:5', 'Acts', 24, 5, '&nbsp;دا سړے زمونږ دپاره ناسور دے چې په ټوله دُنيا کښې د يهوديانو په مينځ کښې فتنه خوروى. او دے د ناصريانو د فرقې مشر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26644, 'Acts 24:6', 'Acts', 24, 6, '&nbsp;دۀ د خُدائ د کور د بې‌حرمتۍ کوشش هم وکړو، نو بيا مونږ هغه ګرفتار کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26645, 'Acts 24:7', 'Acts', 24, 7, '&nbsp;خو لسياس کمان آفسر په مينځ کښې راغلو او دا سړے يې په زبردستۍ سره زمونږ د لاسه وويستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26646, 'Acts 24:8', 'Acts', 24, 8, '&nbsp;کۀ تۀ په خپله د هغۀ نه تپوس وکړې نو تۀ به د هغه هر څۀ نه خبر شې چې مونږ پرې اِلزام لګولے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
