(26689, 'Acts 25:24', 'Acts', 25, 24, '&nbsp;بيا فِستوس ووئيل چې، ”اے اګريپا بادشاه او مونږ سره موجودو ټولو حاضرينو، تاسو دا سړے وينئ د چا په حقله چې ټولو يهوديانو دلته او په يروشلم کښې ما ته خواست کړے دے او دا چغې يې وهلې چې دے نور د ژوندى پاتې کېدو قابل نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26690, 'Acts 25:25', 'Acts', 25, 25, '&nbsp;خو ما ته پته ولګېده چې دۀ داسې څۀ نۀ دى کړى چې ورته دې د مرګ سزا ورکړے شى. او کله چې هغۀ قيصر اعظم ته اپيل وکړو نو ما د هغۀ د لېږلو فېصله وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26691, 'Acts 25:26', 'Acts', 25, 26, '&nbsp;خو ما سره د دۀ په حقله څۀ داسې پوخ اِلزام نشته چې قيصر ته يې وليکم، نو ځکه ما دے ستاسو ټولو په وړاندې او خاص د بادشاه اګريپا په وړاندې پېش کړو، نو چې د دۀ تفتيش کولو نه پس زۀ څۀ وليکم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26692, 'Acts 25:27', 'Acts', 25, 27, '&nbsp;ځکه چې ما ته دا نامناسب ښکارى چې د يو قېدى خلاف څۀ ښکاره جرم نۀ وى او هغه بادشاه ته ولېږلے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26693, 'Acts 26:1', 'Acts', 26, 1, '&nbsp;بيا اګريپا پولوس ته ووئيل چې، ”تا ته د خپل ځان په حقله د خبرو کولو اجازت دے.“ بيا پولوس خپل لاس اوچت کړو او خپله صفائى يې داسې پېش کړله چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26694, 'Acts 26:2', 'Acts', 26, 2, '&nbsp;”اے اګريپا بادشاه. زۀ خپل ځان خوش قِسمته ګڼم چې ستا په وړاندې ولاړ يم او د خپل ځان په حقله د هغه ټولو اِلزامونو صفائى پېش کوم چې يهوديانو راباندې لګولى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26695, 'Acts 26:3', 'Acts', 26, 3, '&nbsp;او خاص تۀ د يهوديانو د رِواجونو او اختلافاتو نه ډېر ښۀ واقف يې نو ځکه تا ته مِنت کوم چې زما خبرې په تسلۍ سره واوره.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26696, 'Acts 26:4', 'Acts', 26, 4, '&nbsp;زما د ځوانۍ نه زما ژوندون ټولو يهوديانو ته معلوم دے چې د شروع نه ما ژوند د خپلو خلقو سره او په يروشلم کښې تير کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26697, 'Acts 26:5', 'Acts', 26, 5, '&nbsp;دوئ ما د ډېر وخت نه پېژنى او کۀ غواړى نو دا تپوس هم کولے شى چې زۀ يو فريسى يم کومه چې زمونږ د مذهب د ټولو نه سخته فرقه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26698, 'Acts 26:6', 'Acts', 26, 6, '&nbsp;او اوس زۀ د هغه وعدې په اُميد دلته د فېصلې دپاره ولاړ يم کومه چې زمونږ د پلار نيکونو سره خُدائ پاک کړې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26699, 'Acts 26:7', 'Acts', 26, 7, '&nbsp;بلکې زمونږ دولس قبيلې د هغې وعدې د پوره کېدو په طمع کښې شپه او ورځ پوره په جوش او جذبې سره عبادت کوى. اے بادشاه سلامته، هم په دې وجه يهوديان په ما اِلزامونه لګوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26700, 'Acts 26:8', 'Acts', 26, 8, '&nbsp;نو دا خلق ولې دا خبره ناممکنه ګڼى چې خُدائ پاک مړى بيا راژوندى کوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');